// Writes public/llms.txt (https://llmstxt.org): a short, curated map of
// FlarePanel for language models, like openpanel.dev/llms.txt. The docs part
// is read from the docs site's sidebar and each page's frontmatter, so it
// follows the docs. The full text lives at docs.flarepanel.dev/llms-full.txt
// (generated by Vocs); /llms-full.txt redirects there (public/_redirects).
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import docsConfig from '../../docs/vocs.config';
import { site } from '../src/lib/site';

interface SidebarItem {
  text: string;
  link?: string;
  items?: SidebarItem[];
}

const root = join(import.meta.dir, '..');
const pages = join(root, '../docs/src/pages');

/** A docs page's `description:` frontmatter, if it has one. */
function describe(link: string): string {
  const base = link === '/' ? 'index' : link.replace(/^\//, '');
  for (const path of [`${base}.mdx`, `${base}/index.mdx`]) {
    try {
      const text = readFileSync(join(pages, path), 'utf8');
      const match = /^description:\s*(.+)$/m.exec(text);
      return match?.[1]?.trim() ?? '';
    } catch {
      // Try the next layout.
    }
  }
  return '';
}

function entry(text: string, url: string, description = ''): string {
  return `- [${text}](${url})${description ? `: ${description}` : ''}`;
}

const sidebar = (docsConfig.sidebar ?? []) as SidebarItem[];
const docSections: string[] = [];
const looseLinks: string[] = [];
for (const item of sidebar) {
  if (item.items?.length) {
    docSections.push(
      `## ${item.text}`,
      ...item.items
        .filter((child) => child.link)
        .map((child) =>
          entry(
            child.text,
            `${site.docs}${child.link === '/' ? '' : child.link}`,
            describe(child.link as string)
          )
        ),
      ''
    );
  } else if (item.link) {
    looseLinks.push(
      entry(
        item.text,
        `${site.docs}${item.link === '/' ? '' : item.link}`,
        describe(item.link)
      )
    );
  }
}

const npmPackages = [
  ['@flarepanel/web', 'browser SDK (JavaScript, React)'],
  ['@flarepanel/nextjs', 'Next.js component and hooks'],
  ['@flarepanel/sdk', 'server and Node.js SDK'],
  ['@flarepanel/react-native', 'React Native SDK'],
  ['@flarepanel/astro', 'Astro component'],
  ['@flarepanel/nuxt', 'Nuxt module'],
  ['@flarepanel/express', 'Express middleware'],
  ['@flarepanel/ai', 'AI observability (LLM calls as events)'],
] as const;

const lines = [
  `# ${site.name}`,
  '',
  `> ${site.description} FlarePanel is an AGPL-3.0 fork of OpenPanel: the same tracking API and SDK calls, with storage and queries on Cloudflare Workers, Durable Objects, D1 and R2.`,
  '',
  '## Main pages',
  entry('Home', `${site.url}/`, 'what FlarePanel is, how it works, FAQ'),
  entry(
    'Dashboard sign-up',
    site.signUp,
    'create a project and get a client ID'
  ),
  entry('Script tag', `${site.url}/op1.js`, 'the hosted browser tracker'),
  '',
  ...docSections,
  ...(looseLinks.length ? ['## More', ...looseLinks, ''] : []),
  '## SDKs on npm',
  ...npmPackages.map(([name, what]) =>
    entry(name, `https://www.npmjs.com/package/${name}`, what)
  ),
  '',
  '## API',
  entry(
    'Tracking API',
    site.api,
    'POST /track with the openpanel-client-id header'
  ),
  '',
  '## Full text',
  entry(
    'llms-full.txt',
    `${site.docs}/llms-full.txt`,
    'every docs page as plain text'
  ),
  '',
  '## Source',
  entry('GitHub', site.github),
  entry('License (AGPL-3.0)', site.license),
  entry('OpenPanel (upstream)', site.openpanel),
  '',
];

writeFileSync(join(root, 'public/llms.txt'), lines.join('\n'));
console.log(`llms.txt: ${lines.length} lines`);
